ARTICLES = [
    ("owasp-cheatsheets", "OWASP Cheat Sheet Series", "sources", "Conseils pratiques de sécurisation des applications, organisés par sujet.", "Utiliser les fiches OWASP pour guider la conception et les revues de code (authentification, sessions, validation, secrets, API, etc.). Vérifier la date et les références propres à chaque fiche, puis adapter les recommandations au framework et au modèle de menace du projet.", "beginner", "informational", ["owasp", "web", "secure-coding"]),
    ("owasp-wstg", "OWASP Web Security Testing Guide", "sources", "Méthodologie d'évaluation de sécurité d'applications Web.", "Le WSTG décrit des objectifs et procédures de vérification. Ne sélectionner que des contrôles autorisés, dans le périmètre approuvé, et préférer l'environnement de test. Les cas pouvant modifier des données ou provoquer une charge doivent être évités en production. La version publiée consultée est 4.2.", "intermediate", "high", ["owasp", "testing", "web"]),
    ("cisa-kev", "CISA Known Exploited Vulnerabilities (KEV)", "sources", "Catalogue officiel de vulnérabilités dont l'exploitation a été observée.", "Utiliser le catalogue KEV pour prioriser la correction des vulnérabilités présentes dans l'inventaire logiciel. Une entrée KEV ne prouve pas que votre système est vulnérable : vérifier produit, versions, configuration et avis éditeur. Le flux JSON officiel est déjà synchronisé par Cybbig.", "beginner", "critical", ["cisa", "kev", "cve", "priorisation"]),
    ("nvd-cve", "NIST National Vulnerability Database", "sources", "Enrichissements et références pour les identifiants CVE.", "La NVD fournit des données structurées sur les vulnérabilités. Les fiches peuvent évoluer : consulter la date de mise à jour, les références éditeur et les avis CERT. Corréler un CVE avec les versions réellement déployées avant de conclure à l'exposition.", "beginner", "high", ["nist", "nvd", "cve"]),
    ("cert-fr", "CERT-FR / ANSSI", "sources", "Alertes et avis français sur les menaces et correctifs.", "Consulter les alertes et avis du CERT-FR pour les recommandations de mitigation et d'application des correctifs. Conserver le lien et la date de synchronisation avec chaque élément de veille. Une alerte générique ne remplace pas l'analyse de l'environnement concerné.", "beginner", "high", ["cert-fr", "anssi", "veille"]),
    ("first-epss", "FIRST EPSS", "sources", "Estimation quotidienne de la probabilité d'exploitation d'un CVE à court terme.", "EPSS estime la probabilité qu'une vulnérabilité soit exploitée dans les 30 jours. Ce score est un signal de priorisation, pas une preuve d'exploitation ni une mesure d'impact métier. FIRST publie les scores quotidiens en CSV et recommande ce fichier ou son dépôt pour les traitements en lot. Attribuer la source et la date du score.", "intermediate", "medium", ["first", "epss", "cve", "priorisation"]),
    ("github-advisories", "GitHub Advisory Database", "sources", "Avis de sécurité affectant des dépendances logicielles open source.", "La base GitHub fournit des avis consultables sur le Web et via API. Faire correspondre l'écosystème, le nom du paquet et la plage de versions ; vérifier les versions corrigées et les liens amont. Respecter les limites d'API et conserver l'identifiant de l'avis.", "intermediate", "high", ["github", "dependencies", "supply-chain"]),
    ("osv", "OSV — Open Source Vulnerabilities", "sources", "Base structurée de vulnérabilités avec plages de versions affectées.", "OSV propose un schéma et une API adaptés à la correspondance entre versions de paquets et avis de vulnérabilité. Valider l'identifiant d'écosystème et la version exacte. Ne pas assimiler une correspondance approximative de nom à une vulnérabilité confirmée.", "intermediate", "high", ["osv", "dependencies", "supply-chain"]),
    ("php-python-docs", "Documentations officielles PHP et Python", "sources", "Références primaires sur les comportements des langages et leurs API.", "Pour les questions de code, préférer le manuel PHP et la documentation Python aux extraits de blogs. Vérifier la version du runtime utilisée par le projet. Points de départ : versions PHP maintenues, PDO prepared statements, Python secrets, subprocess et pickle. Ces références servent aux corrections défensives et à la compréhension du code.", "beginner", "medium", ["php", "python", "documentation"]),
    ("research-papers", "Articles scientifiques en sécurité logicielle", "sources", "Travaux de recherche sur l'analyse et la défense des logiciels.", "Pour interpréter une étude, relever le jeu de données, les métriques, les limites et la date. Une prépublication arXiv n'est pas nécessairement évaluée par les pairs. Exemples : revues sur la détection de vulnérabilités et études USENIX sur les défenses SSRF. Ne pas transformer un résultat expérimental en garantie de sécurité.", "advanced", "informational", ["research", "arxiv", "usenix", "static-analysis"]),
    ("reddit-netsec", "Reddit r/netsec — veille communautaire", "sources", "Discussions communautaires utiles pour découvrir des sujets et outils récents.", "Reddit peut faire émerger des outils, incidents et travaux, mais les messages sont des contributions non vérifiées et peuvent être incomplets ou promotionnels. Utiliser les publications comme pistes uniquement ; confirmer chaque affirmation auprès d'une documentation éditeur, d'un CERT, d'une publication scientifique ou du dépôt officiel. Ne pas exécuter les commandes ou dépôts recommandés sans revue et environnement isolé.", "intermediate", "medium", ["reddit", "community", "verification"]),
]

